let topicDraft=[];
function selectedBattleTopics(subject='mixed'){if(subject!=='mixed'&&BANK[subject])return[subject];const saved=Array.isArray(profile.battleTopics)?profile.battleTopics:['maths'];const valid=[...new Set(saved)].filter(id=>BANK[id]);return valid.length?valid:['maths']}
function chooseBattleTopics(){topicDraft=selectedBattleTopics();drawTopicPicker(false)}
function drawTopicPicker(keepScroll=true){const scroll=keepScroll?(document.querySelector('.topic-picker')?.scrollTop||0):0;const count=topicDraft.length,total=10;openModal(`${topModal('BUILD YOUR BATTLE LOADOUT')}<h2 id="modal-title" class="modal-title">Choose your learning fields.</h2><p class="sub">All 19 fields are available below. Choose any mix: the warm-up is always 10 random questions total. Each correct answer earns +1 heart.</p><div class="topic-quick"><button class="text-btn" data-topic-choice="all">Select all</button><button class="text-btn" data-topic-choice="clear">Clear</button></div><div class="topic-picker">${topicPickerGroups(topicDraft)}</div><div class="topic-summary"><p><b>${count} field${count===1?'':'s'} selected · 10 questions total</b><span>Up to +${total} hearts · ${selectedMode().name} battle</span></p><button class="primary" data-action="start-warmup" ${count?'':'disabled'}>Start warm-up →</button></div>`);const list=document.querySelector('.topic-picker');if(list)list.scrollTop=scroll}
function buildPreparation(subject){const sections=selectedBattleTopics(subject);return{mode:'preparation',subject,sections,deck:buildQuestionDeck(sections).slice(0,10),pos:0,right:0,chain:0,bestChain:0,sectionScores:{}}}
function recordPreparationAnswer(right){const id=quiz.item.id;quiz.sectionScores[id]??={correct:0,total:0};quiz.sectionScores[id].total++;quiz.sectionScores[id].correct+=+right;const hint=document.querySelector('#modal-content .hint');if(hint)hint.textContent='♥ '+quiz.right+' extra hearts earned · 10 questions total · Take your time.';quiz.chain=right?quiz.chain+1:0;quiz.bestChain=Math.max(quiz.bestChain,quiz.chain);game.hp=game.hero.hp+quiz.right;game.questionsRight=quiz.right;game.questionsAnswered=quiz.pos+1;game.bestChain=quiz.bestChain;const feedback=document.querySelector('#answer-feedback');if(feedback)feedback.insertAdjacentHTML('beforeend',`<div class="earned-life">${right?'♥ +1 HEART EARNED':'Keep learning — the next heart is waiting.'}<span>${quiz.right*10} preparation points · ${game.hp} hearts earned so far</span></div>`)}
function preparationResults(){const g=game;g.preparationRight=quiz.right;g.questionsRight=quiz.right;g.questionsAnswered=quiz.deck.length;g.bestChain=quiz.bestChain;g.hp=g.hero.hp+quiz.right;g.maxHp=g.hero.hp+quiz.deck.length;g.prepared=true;const total=quiz.deck.length,right=quiz.right,sections=Object.entries(quiz.sectionScores).map(([id,score])=>'<div><span>'+SUBJECTS.find(s=>s.id===id).name+'</span><b>'+score.correct+' / '+score.total+'</b></div>').join('');quiz=null;GameAudio.effect('win');openModal(`${topModal('WARM-UP COMPLETE')}<div class="results loadout-results"><div class="result-emblem">♥</div><span class="result-kicker">YOUR KNOWLEDGE. YOUR BATTLE LIFE.</span><h2 id="modal-title">${g.hp} hearts, earned.</h2><p>${right} correct out of ${total} questions from ${fieldIdsFor(g.topicIds).length} selected field${fieldIdsFor(g.topicIds).length===1?'':'s'}.</p><div class="section-results">${sections}</div><div class="loadout-equation"><span><b>${g.hero.hp}</b>AVATAR BASE</span><i>+</i><span><b>${right}</b>CORRECT ANSWERS</span><i>=</i><span><b>${g.hp} ♥</b>BATTLE LIFE</span></div><div class="earned-bar"><i style="width:${g.hp/g.maxHp*100}%"></i></div><p class="notice">${right*10} preparation points · Every correct answer added one heart.<br>Potential life: ${g.maxHp} hearts. Your starting life: ${g.hp}.</p><div class="modal-actions" style="justify-content:center"><button class="primary" data-action="enter-battle">Enter ${g.mode.name} arena →</button><button class="secondary" data-action="leave">Back to home</button></div></div>`)}
function enterPreparedBattle(){if(!game?.prepared)return;closeModal();game.paused=false;game.rechargeCooldown=0;game.invincible=1.5;resetControls();last=performance.now();$('#arena').focus()}
function cancelPreparation(){openModal(`${topModal('LEAVE WARM-UP?')}<h2 id="modal-title">Your learning XP is saved.</h2><p class="feedback">Finish all ${quiz.deck.length} questions to turn correct answers into battle life. Leaving ends this warm-up.</p><div class="modal-actions"><button class="primary" data-action="continue-warmup">Continue warm-up →</button><button class="secondary" data-action="leave">Leave warm-up</button></div>`)}
function reloadEnergy(){const g=game;if(!g||g.paused)return;if(g.rechargeCooldown>0){toast('Reload ready in '+Math.ceil(g.rechargeCooldown)+' seconds.');return}if(g.ammo>=g.maxAmmo){toast('Energy is full.');return}g.ammo=Math.min(g.maxAmmo,g.ammo+3);g.rechargeCooldown=g.mode.recharge;GameAudio.effect('pickup');g.floaters.push({x:g.x,y:g.y-60,text:'+3 ENERGY',colour:'#c0f8e3',life:1})}
